@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=Outfit:wght@400;500;600;700;800&display=swap');

:root {
  --primary: #028090;
  --primary-dark: #015965;
  --primary-light: #e6f4f6;
  --secondary: #00a896;
  --secondary-light: #e0f7f4;
  --accent-gold: #f4a261;
  --accent-red: #e63946;
  --accent-green: #2a9d8f;

  --text-main: #0f172a;
  --text-body: #334155;
  --text-muted: #64748b;
  --text-white: #ffffff;

  --bg-page: #f8fafc;
  --bg-card: #ffffff;
  --bg-subtle: #f1f5f9;

  --border: #e2e8f0;
  --border-focus: #00a896;

  --radius-sm: 8px;
  --radius-md: 14px;
  --radius-lg: 24px;
  --radius-full: 9999px;

  --shadow-sm: 0 4px 12px rgba(2, 128, 144, 0.05);
  --shadow-md: 0 10px 25px rgba(2, 128, 144, 0.08);
  --shadow-lg: 0 20px 40px rgba(2, 128, 144, 0.12);
  --shadow-glow: 0 0 20px rgba(0, 168, 150, 0.25);

  --font-heading: 'Outfit', sans-serif;
  --font-body: 'Plus Jakarta Sans', sans-serif;
  --transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

/* Base Styles */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-body);
  background-color: var(--bg-page);
  color: var(--text-body);
  line-height: 1.6;
  overflow-x: hidden;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  color: var(--text-main);
  line-height: 1.25;
  font-weight: 700;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  cursor: pointer;
  border: none;
  background: none;
  font-family: var(--font-body);
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

/* Container */
.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
}

/* Top Utility Bar */
.top-bar {
  background: linear-gradient(90deg, #015965 0%, #028090 100%);
  color: var(--text-white);
  padding: 8px 0;
  font-size: 0.875rem;
}

.top-bar-content {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
}

.top-info-group {
  display: flex;
  align-items: center;
  gap: 20px;
  flex-wrap: wrap;
}

.top-info-item {
  display: flex;
  align-items: center;
  gap: 6px;
  opacity: 0.95;
  transition: var(--transition);
}

.top-info-item:hover {
  opacity: 1;
  color: #70e4d5;
}

.top-emergency-badge {
  background: var(--accent-red);
  color: white;
  padding: 4px 12px;
  border-radius: var(--radius-full);
  font-weight: 700;
  font-size: 0.8rem;
  display: flex;
  align-items: center;
  gap: 6px;
  animation: pulse-red 2s infinite;
}

@keyframes pulse-red {
  0% { box-shadow: 0 0 0 0 rgba(230, 57, 70, 0.7); }
  70% { box-shadow: 0 0 0 10px rgba(230, 57, 70, 0); }
  100% { box-shadow: 0 0 0 0 rgba(230, 57, 70, 0); }
}

/* Main Navbar */
.site-header {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: rgba(255, 255, 255, 0.94);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(226, 232, 240, 0.8);
  box-shadow: var(--shadow-sm);
  transition: var(--transition);
}

.navbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 80px;
}

/* Brand Logo */
.brand-logo {
  display: flex;
  align-items: center;
  gap: 12px;
}

.logo-icon-wrap {
  width: 48px;
  height: 48px;
  background: linear-gradient(135deg, var(--primary) 0%, var(--secondary) 100%);
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  box-shadow: 0 6px 16px rgba(0, 168, 150, 0.3);
}

.brand-text-wrap {
  display: flex;
  flex-direction: column;
}

.brand-name {
  font-size: 1.4rem;
  font-weight: 800;
  color: var(--primary-dark);
  letter-spacing: -0.5px;
  line-height: 1.1;
}

.brand-name span {
  color: var(--secondary);
}

.brand-tagline {
  font-size: 0.725rem;
  font-weight: 600;
  color: var(--text-muted);
  letter-spacing: 0.5px;
  text-transform: uppercase;
}

/* Dropdown Navigation Menu */
.nav-menu {
  display: flex;
  align-items: center;
  gap: 8px;
  list-style: none;
}

.nav-item {
  position: relative;
}

.nav-link {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 10px 16px;
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text-body);
  border-radius: var(--radius-sm);
  transition: var(--transition);
}

.nav-link:hover,
.nav-link.active {
  color: var(--primary);
  background-color: var(--primary-light);
}

.dropdown-chevron {
  width: 14px;
  height: 14px;
  transition: transform 0.25s ease;
}

.nav-item:hover .dropdown-chevron {
  transform: rotate(180deg);
}

/* Dropdown Menu Container */
.dropdown-menu {
  position: absolute;
  top: 100%;
  left: 0;
  min-width: 260px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  padding: 12px;
  opacity: 0;
  visibility: hidden;
  transform: translateY(12px);
  transition: all 0.25s cubic-bezier(0.16, 1, 0.3, 1);
  z-index: 1100;
}

.nav-item:hover .dropdown-menu {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.dropdown-link {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 12px;
  border-radius: var(--radius-sm);
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--text-body);
  transition: var(--transition);
}

.dropdown-link:hover {
  background: var(--primary-light);
  color: var(--primary-dark);
  transform: translateX(4px);
}

.dropdown-icon {
  width: 32px;
  height: 32px;
  border-radius: 8px;
  background: var(--bg-subtle);
  color: var(--primary);
  display: flex;
  align-items: center;
  justify-content: center;
}

.dropdown-link:hover .dropdown-icon {
  background: var(--secondary);
  color: white;
}

/* Mega Menu for Departments */
.dropdown-menu.mega-menu {
  min-width: 640px;
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 8px;
  padding: 16px;
  left: -120px;
}

/* Action Buttons */
.header-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 22px;
  font-size: 0.925rem;
  font-weight: 700;
  border-radius: var(--radius-sm);
  transition: var(--transition);
}

.btn-primary {
  background: linear-gradient(135deg, var(--primary) 0%, var(--secondary) 100%);
  color: white;
  box-shadow: 0 4px 14px rgba(0, 168, 150, 0.35);
}

.btn-primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 22px rgba(0, 168, 150, 0.45);
}

.btn-outline {
  border: 2px solid var(--primary);
  color: var(--primary);
  background: transparent;
}

.btn-outline:hover {
  background: var(--primary-light);
  color: var(--primary-dark);
}

.btn-emergency {
  background: var(--accent-red);
  color: white;
  box-shadow: 0 4px 14px rgba(230, 57, 70, 0.35);
}

.btn-emergency:hover {
  background: #c92a37;
  transform: translateY(-2px);
}

/* Mobile Toggle */
.mobile-toggle {
  display: none;
  font-size: 1.5rem;
  color: var(--text-main);
}

/* Page Section View Switcher */
.page-view {
  display: none;
  animation: fadeIn 0.4s ease forwards;
}

.page-view.active-view {
  display: block;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

/* HERO SECTION */
.hero-section {
  position: relative;
  background: linear-gradient(135deg, #f0fdfa 0%, #e6f4f6 50%, #f8fafc 100%);
  padding: 60px 0 80px;
  overflow: hidden;
}

.hero-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 40px;
  align-items: center;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: white;
  border: 1px solid rgba(0, 168, 150, 0.3);
  padding: 6px 16px;
  border-radius: var(--radius-full);
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--primary);
  margin-bottom: 20px;
  box-shadow: var(--shadow-sm);
}

.hero-title {
  font-size: 3rem;
  font-weight: 800;
  line-height: 1.15;
  margin-bottom: 20px;
  color: var(--primary-dark);
}

.hero-title span {
  color: var(--secondary);
  background: linear-gradient(135deg, var(--primary) 0%, var(--secondary) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.hero-desc {
  font-size: 1.1rem;
  color: var(--text-body);
  margin-bottom: 30px;
  max-width: 540px;
}

.hero-cta-group {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
  margin-bottom: 40px;
}

.hero-features-list {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
}

.hero-feature-item {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--text-main);
}

.hero-feature-icon {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--secondary-light);
  color: var(--secondary);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.hero-image-card {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-lg);
  border: 4px solid white;
}

.hero-image-card img {
  width: 100%;
  height: 480px;
  object-fit: cover;
}

.hero-floating-card {
  position: absolute;
  bottom: 24px;
  left: 24px;
  background: rgba(255, 255, 255, 0.95);
  backdrop-filter: blur(10px);
  padding: 16px 20px;
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-md);
  display: flex;
  align-items: center;
  gap: 16px;
  border: 1px solid var(--border);
}

.floating-icon {
  width: 44px;
  height: 44px;
  background: var(--primary-light);
  color: var(--primary);
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* Quick Action / Booking Strip */
.quick-booking-bar {
  margin-top: -40px;
  position: relative;
  z-index: 200;
}

.booking-strip-card {
  background: white;
  border-radius: var(--radius-md);
  padding: 24px 32px;
  box-shadow: var(--shadow-lg);
  border: 1px solid var(--border);
  display: grid;
  grid-template-columns: repeat(4, 1fr) auto;
  gap: 16px;
  align-items: center;
}

.input-field-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.input-field-group label {
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
  color: var(--text-muted);
}

.input-field-group select,
.input-field-group input {
  padding: 12px 14px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  font-size: 0.925rem;
  font-family: var(--font-body);
  color: var(--text-main);
  background: var(--bg-page);
  outline: none;
  transition: var(--transition);
}

.input-field-group select:focus,
.input-field-group input:focus {
  border-color: var(--primary);
  background: white;
  box-shadow: 0 0 0 3px rgba(2, 128, 144, 0.1);
}

/* STATS SECTION */
.stats-section {
  padding: 60px 0;
  background: white;
  border-bottom: 1px solid var(--border);
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 20px;
  text-align: center;
}

.stat-card {
  padding: 20px;
  border-radius: var(--radius-md);
  background: var(--bg-page);
  border: 1px solid var(--border);
  transition: var(--transition);
}

.stat-card:hover {
  transform: translateY(-4px);
  border-color: var(--secondary);
  box-shadow: var(--shadow-md);
}

.stat-number {
  font-size: 2.4rem;
  font-weight: 800;
  color: var(--primary);
  line-height: 1.1;
  font-family: var(--font-heading);
}

.stat-label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-muted);
  margin-top: 6px;
}

/* SECTION TITLES */
.section-header {
  text-align: center;
  max-width: 680px;
  margin: 0 auto 48px;
}

.section-subtitle {
  font-size: 0.85rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: var(--secondary);
  margin-bottom: 8px;
  display: block;
}

.section-title {
  font-size: 2.2rem;
  font-weight: 800;
  color: var(--text-main);
  margin-bottom: 12px;
}

.section-desc {
  font-size: 1rem;
  color: var(--text-muted);
}

/* DEPARTMENTS GRID */
.departments-section {
  padding: 80px 0;
}

.departments-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.dept-card {
  background: white;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 28px 24px;
  transition: var(--transition);
  display: flex;
  flex-direction: column;
  gap: 16px;
  position: relative;
  overflow: hidden;
}

.dept-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 4px;
  background: linear-gradient(90deg, var(--primary), var(--secondary));
  opacity: 0;
  transition: var(--transition);
}

.dept-card:hover {
  transform: translateY(-6px);
  box-shadow: var(--shadow-md);
  border-color: var(--secondary);
}

.dept-card:hover::before {
  opacity: 1;
}

.dept-icon {
  width: 56px;
  height: 56px;
  border-radius: 14px;
  background: var(--primary-light);
  color: var(--primary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  transition: var(--transition);
}

.dept-card:hover .dept-icon {
  background: var(--secondary);
  color: white;
}

.dept-name {
  font-size: 1.2rem;
  font-weight: 700;

}

.dept-desc {
  font-size: 0.9rem;
  color: var(--text-muted);
  flex-grow: 1;
}

.dept-link {
  font-size: 0.875rem;
  font-weight: 700;
  color: var(--primary);
  display: flex;
  align-items: center;
  gap: 6px;
}

/* DOCTORS DIRECTORY */
.doctors-section {
  padding: 80px 0;
  background: var(--bg-subtle);
}

.doctors-filter-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 32px;
  flex-wrap: wrap;
  background: white;
  padding: 16px 24px;
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-sm);
}

.doctor-search-input {
  flex: 1;
  min-width: 260px;
  padding: 10px 16px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  font-size: 0.9rem;
  outline: none;
}

.doctors-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.doctor-card {
  background: white;
  border-radius: var(--radius-md);
  overflow: hidden;
  border: 1px solid var(--border);
  box-shadow: var(--shadow-sm);
  transition: var(--transition);
  display: flex;
  flex-direction: column;
}

.doctor-card:hover {
  transform: translateY(-6px);
  box-shadow: var(--shadow-md);
}

.doctor-img-wrap {
  position: relative;
  height: 240px;
  overflow: hidden;
  background: var(--bg-subtle);
}

.doctor-img-wrap img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.4s ease;
}

.doctor-card:hover .doctor-img-wrap img {
  transform: scale(1.05);
}

.doctor-badge {
  position: absolute;
  top: 12px;
  right: 12px;
  background: rgba(2, 128, 144, 0.9);
  color: white;
  padding: 4px 10px;
  border-radius: var(--radius-full);
  font-size: 0.75rem;
  font-weight: 700;
}

.doctor-info {
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex-grow: 1;
}

.doctor-dept {
  font-size: 0.775rem;
  font-weight: 800;
  text-transform: uppercase;
  color: var(--secondary);
}

.doctor-name {
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--text-main);
}

.doctor-degree {
  font-size: 0.85rem;
  color: var(--text-muted);
}

.doctor-exp {
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--primary-dark);
  background: var(--primary-light);
  padding: 4px 10px;
  border-radius: 6px;
  display: inline-block;
  margin-top: 4px;
}

.doctor-footer {
  padding: 16px 20px;
  border-top: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: #fafafa;
}

.doctor-fee {
  font-size: 0.9rem;
  font-weight: 700;
  color: var(--text-main);
}

/* FACILITIES SECTION */
.facilities-section {
  padding: 80px 0;
}

.facilities-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 28px;
}

.facility-card {
  background: white;
  border-radius: var(--radius-md);
  overflow: hidden;
  border: 1px solid var(--border);
  box-shadow: var(--shadow-sm);
  transition: var(--transition);
}

.facility-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}

.facility-img-wrap {
  height: 200px;
  overflow: hidden;
}

.facility-img-wrap img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.facility-content {
  padding: 24px;
}

.facility-title {
  font-size: 1.2rem;
  font-weight: 700;
  margin-bottom: 8px;
}

.facility-desc {
  font-size: 0.9rem;
  color: var(--text-muted);
}

/* GALLERY GRID */
.gallery-section {
  padding: 80px 0;
  background: var(--bg-subtle);
}

.gallery-filters {
  display: flex;
  justify-content: center;
  gap: 12px;
  margin-bottom: 36px;
  flex-wrap: wrap;
}

.filter-btn {
  padding: 8px 20px;
  border-radius: var(--radius-full);
  background: white;
  border: 1px solid var(--border);
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-body);
  transition: var(--transition);
}

.filter-btn:hover,
.filter-btn.active {
  background: var(--primary);
  color: white;
  border-color: var(--primary);
}

.gallery-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.gallery-item {
  position: relative;
  border-radius: var(--radius-md);
  overflow: hidden;
  height: 260px;
  box-shadow: var(--shadow-sm);
  cursor: pointer;
}

.gallery-item img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.4s ease;
}

.gallery-item:hover img {
  transform: scale(1.08);
}

.gallery-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(0deg, rgba(1, 89, 101, 0.9) 0%, rgba(1, 89, 101, 0.2) 60%, transparent 100%);
  opacity: 0;
  transition: var(--transition);
  padding: 20px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  color: white;
}

.gallery-item:hover .gallery-overlay {
  opacity: 1;
}

/* TESTIMONIALS SECTION */
.testimonials-section {
  padding: 80px 0;
  background: white;
}

.testimonials-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.testimonial-card {
  background: var(--bg-page);
  padding: 28px;
  border-radius: var(--radius-md);
  border: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.stars {
  color: var(--accent-gold);
  font-size: 1rem;
}

.quote-text {
  font-style: italic;
  color: var(--text-body);
  font-size: 0.95rem;
  flex-grow: 1;
}

.author-info {
  display: flex;
  align-items: center;
  gap: 12px;
  border-top: 1px solid var(--border);
  padding-top: 12px;
}

